select case when rating >= 4.3 then 'HIGH' else 'LOW' end as rating_tier, count_if(city = 'London') as london_events, count_if(country = 'US') as us_events, count(*) filter (where city = 'New York') as new_york_rows, sum(rating) as total_rating, size(collect_set(country)) as num_countries from suppliers group by case when rating >= 4.3 then 'HIGH' else 'LOW' end order by num_countries desc nulls last;
